/* Basic accessible stylesheet for GOV-R08 replica */
:root {
    --color-bg: #ffffff;
    --color-text: #222222;
    --color-primary: #003366;
    --color-accent: #ffbf47;
    --color-muted: #666666;
    --color-border: #cccccc;
    --color-alert-bg: #fffbcc;
    --color-alert-border: #ffcc00;
    --color-focus-outline: #ffbf47;
}

/* Reset */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}
html { font-size: 100%; }
body {
    font-family: system-ui, sans-serif;
    line-height: 1.5;
    background: var(--color-bg);
    color: var(--color-text);
}
img { max-width: 100%; height: auto; }
a { color: var(--color-primary); text-decoration: underline; }
a:hover,
a:focus { color: var(--color-accent); }
button,
input,
select,
textarea {
    font: inherit;
}

/* Skip link */
.skip-link {
    position: absolute;
    left: -999px;
    top: auto;
    width: 1px;
    height: 1px;
    overflow: hidden;
}
.skip-link:focus {
    left: 0;
    top: 0;
    width: auto;
    height: auto;
    overflow: visible;
    background: var(--color-bg);
    color: var(--color-text);
    padding: .5rem 1rem;
    z-index: 100;
}

/* Header */
.site-header {
    background: var(--color-primary);
    color: #fff;
    padding: 1rem;
}
.site-header .logo {
    font-weight: bold;
    font-size: 1.25rem;
}
.site-header .demo-lang {
    margin-left: 1rem;
    font-size: .875rem;
}

/* Navigation */
.primary-nav {
    background: #e6efff;
}
.primary-nav ul {
    list-style: none;
    display: flex;
    flex-wrap: wrap;
    gap: .5rem;
    padding: .5rem 1rem;
}
.primary-nav a {
    display: block;
    padding: .25rem .5rem;
    border-radius: .25rem;
    text-decoration: none;
    color: var(--color-text);
}
.primary-nav a:hover,
.primary-nav a:focus {
    background: var(--color-accent);
    color: #fff;
}

/* Hero */
.hero-banner {
    background: #e6f0ff;
    padding: 2rem 1rem;
    text-align: center;
}
.hero-banner h2 {
    margin-top: .5rem;
    font-size: 1.5rem;
}

/* Alert banner */
.alert-banner {
    display: none; /* toggled by JS */
    background: var(--color-alert-bg);
    border-left: .25rem solid var(--color-alert-border);
    padding: .75rem 1rem;
    margin: 1rem;
    role: alert;
}
.alert-banner[hidden] { display: none; }
.alert-banner button {
    background: transparent;
    border: none;
    color: var(--color-primary);
    font-weight: bold;
    margin-left: 1rem;
    cursor: pointer;
}

/* Content band */
.content-band {
    padding: 1rem;
}
.content-band h1 {
    font-size: 2rem;
    margin-bottom: .5rem;
}
.content-band h2 {
    font-size: 1.5rem;
    margin-top: 1.5rem;
    margin-bottom: .5rem;
}
.content-band p {
    margin-bottom: 1rem;
}

/* Search form */
.search-form {
    margin: 1rem 0;
    display: flex;
    gap: .5rem;
    flex-wrap: wrap;
}
.search-form input[type="search"] {
    flex: 1 1 200px;
    padding: .25rem .5rem;
    border: 1px solid var(--color-border);
    border-radius: .25rem;
}
.search-form button {
    padding: .25rem .75rem;
    background: var(--color-primary);
    color: #fff;
    border: none;
    border-radius: .25rem;
    cursor: pointer;
}
.search-form button:hover,
.search-form button:focus {
    background: var(--color-accent);
}
#search-results {
    margin-top: 1rem;
}
#search-results ul {
    list-style: none;
    padding: 0;
}
#search-results li {
    padding: .25rem .5rem;
    border-bottom: 1px solid var(--color-border);
}

/* Calendar widget */
.calendar-widget {
    margin: 1rem 0;
    display: flex;
    align-items: center;
    gap: .5rem;
    flex-wrap: wrap;
}
.calendar-widget button {
    background: var(--color-primary);
    color: #fff;
    border: none;
    padding: .25rem .5rem;
    border-radius: .25rem;
    cursor: pointer;
}
.calendar-widget button:hover,
.calendar-widget button:focus {
    background: var(--color-accent);
}
.calendar-widget span {
    font-weight: bold;
}

/* Report form */
.report-form {
    background: #f9f9f9;
    padding: 1rem;
    border: 1px solid var(--color-border);
    border-radius: .25rem;
    margin-top: 1rem;
}
.report-form label {
    display: block;
    margin-bottom: .25rem;
    font-weight: bold;
}
.report-form input,
.report-form textarea {
    width: 100%;
    padding: .25rem .5rem;
    border: 1px solid var(--color-border);
    border-radius: .25rem;
    margin-bottom: .5rem;
}
.report-form button {
    background: var(--color-primary);
    color: #fff;
    border: none;
    padding: .25rem .75rem;
    border-radius: .25rem;
    cursor: pointer;
}
.report-form button:hover,
.report-form button:focus {
    background: var(--color-accent);
}
.error-message {
    color: #b00020;
    font-size: .875rem;
    margin-top: -.25rem;
    margin-bottom: .5rem;
    display: none;
}
.error-summary {
    background: #ffe6e6;
    border: 1px solid #b00020;
    padding: .75rem;
    margin-bottom: 1rem;
    display: none;
}
.error-summary h3 {
    margin-top: 0;
}
.error-summary ul {
    margin: .5rem 0 0 1.5rem;
}

/* Footer */
.site-footer {
    background: #f0f0f0;
    padding: 1rem;
    text-align: center;
    font-size: .875rem;
    color: var(--color-muted);
}

/* Focus outline */
button:focus,
input:focus,
select:focus,
textarea:focus,
a:focus {
    outline: 2px solid var(--color-focus-outline);
    outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
    }
}
